func (f *TextFormatter) recoverValue(b *bytes.Buffer, v any, method string) {
	if r := recover(); r != nil {
		rv := reflect.ValueOf(v)
		if rv.Kind() == reflect.Pointer && rv.IsNil() {
			f.appendString(b, "<nil>")
