// Run takes a testing suite and runs all of the tests attached
// to it.
func Run(t *testing.T, suite TestingSuite) {
	defer recoverAndFailOnPanic(t)

	suite.SetT(t)
	suite.SetS(suite)

	var stats *SuiteInformation
	if _, ok := suite.(WithStats); ok {
		stats = newSuiteInformation()
	}

	var tests []test
	methodFinder := reflect.TypeOf(suite)
	suiteName := methodFinder.Elem().Name()

	var matchMethodRE *regexp.Regexp
	if *matchMethod != "" {
		var err error
		matchMethodRE, err = regexp.Compile(*matchMethod)
		if err != nil {
			fmt.Fprintf(os.Stderr, "testify: invalid regexp for -m: %s\n", err)
			os.Exit(1)
		}
	}

	for i := 0; i < methodFinder.NumMethod(); i++ {
		method := methodFinder.Method(i)

		if !strings.HasPrefix(method.Name, "Test") {
			continue
		}

		if matchMethodRE != nil && !matchMethodRE.MatchString(method.Name) {
			continue
		}

		if method.Type.NumIn() > 1 || method.Type.NumOut() > 0 {
			tests = append(tests, test{
				name:	method.Name,
				run: func(t *testing.T) {
					t.Errorf(
						"testify: suite method %q has invalid signature: expected no input or output parameters, method has %d input parameters and %d output parameters",
						method.Name, method.
// ... (truncated)

// Assert returns an assert context for suite. Normally, you can call:
//
//	suite.NoError(err)
//
// But for situations where the embedded methods are overridden (for example,
// you might want to override assert.Assertions with require.Assertions), this
// method is provided so you can call:
//
//	suite.Assert().NoError(err)
func (suite *Suite) Assert() *assert.Assertions {
	suite.mu.Lock()
	defer suite.mu.Unlock()
	if suite.Assertions == nil {
		panic("'Assert' must not be called before 'Run' or 'SetT'")
	}
	return suite.Assertions
}

// Require returns a require context for suite.
func (suite *Suite) Require() *require.Assertions {
	suite.mu.Lock()
	defer suite.mu.Unlock()
	if suite.require == nil {
		panic("'Require' must not be called before 'Run' or 'SetT'")
	}
	return suite.require
}

// Run provides suite functionality around golang subtests.  It should be
// called in place of t.Run(name, func(t *testing.T)) in test suite code.
// The passed-in func will be executed as a subtest with a fresh instance of t.
// Provides compatibility with go test pkg -run TestSuite/TestName/SubTestName.
func (suite *Suite) Run(name string, subtest func()) bool {
	oldT := suite.T()

	return oldT.Run(name, func(t *testing.T) {
		suite.SetT(t)
		defer suite.SetT(oldT)

		defer recoverAndFailOnPanic(t)

		if setupSubTest, ok := suite.s.(SetupSubTest); ok {
			setupSubTest.SetupSubTest()
		}

		if tearDownSubTest, ok := suite.s.(TearDownSubTest); ok {
			defer tearDownSubTest.TearDownSubTest()
		}

		subtest()
	})
}

// SetS needs to set the current test suite as parent
// to get access to the parent methods
func (suite *Suite) SetS(s TestingSuite) {
	suite.s = s
}

// SetT sets the current *testing.T context.
func (suite *Suite) SetT(t *testing.T) {
	suite.mu.Lock()
	defer suite.mu.Unlock()
	suite.t = t
	suite.Assertions = assert.New(t)
	suite.require = require.New(t)
}

// T retrieves the current *testing.T context.
func (suite *Suite) T() *testing.T {
	suite.mu.RLock()
	defer suite.mu.RUnlock()
	return suite.t
}

func (s *SuiteInformation) Passed() bool {
	for _, stats := range s.TestStats {
		if !stats.Passed {
			return false
		}
	}

	return true
}

func (s *SuiteInformation) end(testName string, passed bool) {
	if s == nil {
		return
	}
	s.TestStats[testName].End = time.Now()
	s.TestStats[testName].Passed = passed
}

func (s *SuiteInformation) start(testName string) {
	if s == nil {
		return
	}
	s.TestStats[testName] = &TestInformation{
		TestName:	testName,
		Start:		time.Now(),
	}
}

func failOnPanic(t *testing.T, r interface{}) {
	t.Helper()
	if r != nil {
		t.Errorf("test panicked: %v\n%s", r, debug.Stack())
		t.FailNow()
	}
}

func newSuiteInformation() *SuiteInformation {
	return &SuiteInformation{
		TestStats: make(map[string]*TestInformation),
	}
}

func recoverAndFailOnPanic(t *testing.T) {
	t.Helper()
	r := recover()
	failOnPanic(t, r)
}

func runTests(t *testing.T, tests []test) {
	if len(tests) == 0 {
		t.Log("warning: no tests to run")
		return
	}

	for _, test := range tests {
		t.Run(test.name, test.run)
	}
}

// AddAuthTokenHeader adds an authentication token header for the host specified by the request.
func AddAuthTokenHeader(rt http.RoundTripper, cfg config) http.RoundTripper {
	return &funcTripper{roundTrip: func(req *http.Request) (*http.Response, error) {

		if req.Header.Get(authorization) != "" {
			return rt.RoundTrip(req)
		}

		var redirectHostnameChange bool
		if req.Response != nil && req.Response.Request != nil {
			redirectHostnameChange = getHostname(req) != getHostname(req.Response.Request)
		}

		if redirectHostnameChange {
			return rt.RoundTrip(req)
		}

		hostnameInRequest := ghauth.NormalizeHostname(getHostname(req))
		token, _ := cfg.ActiveToken(hostnameInRequest)
		if token == "" {

			if canonicalHost, ok := cfg.HostForAPIHost(hostnameInRequest); ok {
				token, _ = cfg.ActiveToken(canonicalHost)
			}
		}
		if token != "" {
			req.Header.Set(authorization, fmt.Sprintf("token %s", token))
		}

		return rt.RoundTrip(req)
	}}
}

