// BeginTelemetry starts an attachment event at full sampling for the raw supplied count.
// A zero count returns nil without changing sampling. recorder is required;
// use a no-op service when telemetry is disabled.
// Call immediately before Flag.UserAssets so invalid and over-limit inputs count.
func BeginTelemetry(recorder ghtelemetry.InvocationRecorder, command string, attachCount int) *TelemetryEvent {
	if attachCount == 0 {
		return nil
	}

	recorder.SetSampleRate(ghtelemetry.SAMPLE_ALL)
	pendingEvent := recorder.Begin(ghtelemetry.Event{
		Type:	"attachment_invocation",
		Dimensions: ghtelemetry.Dimensions{
			"command": command,
		},
		Measures: ghtelemetry.Measures{
			"attach_count":		int64(attachCount),
			"append_ops_count":	0,
			"replace_ops_count":	0,
		},
	})

	return &TelemetryEvent{
		pendingEvent: pendingEvent,
	}
}

// Changed reports whether the attachment flag was passed.
func (f *Flag) Changed() bool {
	return f.flag.Changed
}

// Count returns the number of supplied attachment values before validation.
// Absent flags count as zero; empty paths and values over the limit still count.
func (f *Flag) Count() int {
	return len(f.values)
}

// UserAssets validates the files named by the attachment flag, keeping them in
// the order they were written. It returns nothing when the flag was not passed.
func (f *Flag) UserAssets() ([]UserAsset, error) {
	if !f.Changed() {
		return nil, nil
	}
	if len(f.values) > maxAttachments {
		return nil, fmt.Errorf("`--attach` accepts at most %d values per command", maxAttachments)
	}
	return userAssetsFromArgs(f.values)
}

// NewTestAssets returns a UserAsset per name, resolved through --attach, which
// is the only way a command builds one.
//
// It writes each name into a temporary directory and changes the working
// directory to it for the rest of the test, so the names are relative paths
// that resolve. A name may include directories, which are created.
func NewTestAssets(t *testing.T, names ...string) []UserAsset {
	t.Helper()

	t.Chdir(t.TempDir())

	argv := make([]string, 0, len(names)*2)
	for _, name := range names {
		require.NoError(t, os.MkdirAll(filepath.Dir(name), 0o755))
		require.NoError(t, os.WriteFile(name, []byte("the bytes"), 0o600))
		argv = append(argv, "--attach", "./"+name)
	}

	cmd := &cobra.Command{}
	attachFlag := AddFlag(cmd)
	require.NoError(t, cmd.Flags().Parse(argv))

	assets, err := attachFlag.UserAssets()
	require.NoError(t, err)
	return assets
}

// NewUploader prepares uploads against targetRepository, the numeric REST id of
// the repository the assets are uploaded against, and viewerPermission, the
// GraphQL viewerPermission field on that same repository. It validates
// everything an upload needs, so a caller that gets an Uploader back can use
// it.
//
// The host is checked first. On an enterprise server no token and no permission
// makes an upload work, so any other order would name a fault the user cannot
// fix. The other checks are free to move.
func NewUploader(httpClient *http.Client, tokenType gh.TokenType, host string, targetRepository int64, viewerPermission string) (*Uploader, error) {
	if err := checkHost(host); err != nil {
		return nil, err
	}

	if err := checkUploadTokenType(tokenType); err != nil {
		return nil, err
	}

	if targetRepository <= 0 {
		return nil, errors.New("could not determine which repository to attach files to")
	}

	if err := checkPermission(viewerPermission); err != nil {
		return nil, err
	}

	return &Uploader{client: api.NewClientFromHTTP(httpClient), host: host, targetRepository: targetRepository}, nil
}

// SplitFileArg splits an argument of the form <file>#<text>, the way --attach
// reads '<file>#<image alt text>'. An existing path wins over the delimiter,
// since `#` is legal in filenames. path is arg itself when there was no `#` to
// split at. gh issue artifact create uses it for <file>#<name>, so `#` means
// the same there as in --attach.
func SplitFileArg(arg string) (path, text string) {
	if _, err := os.Stat(arg); err == nil {
		return arg, ""
	}

	for i := strings.LastIndex(arg, "#"); i > 0; i = strings.LastIndex(arg[:i], "#") {
		if _, err := os.Stat(arg[:i]); err == nil {
			return arg[:i], arg[i+1:]
		}
	}

	if idx := strings.LastIndex(arg, "#"); idx > 0 {
		return arg[:idx], arg[idx+1:]
	}
	return arg, ""
}

// StubUpload registers one upload of name against repositoryID, answering with
