// appendParagraph joins two pieces of markdown as separate paragraphs.
func appendParagraph(md, addition string) string {
	if addition == "" {
		return md
	}
	md = strings.TrimRight(md, " \t\r\n")
	if md == "" {
		return addition
	}
	return md + "\n\n" + addition
}

// appendUnreferenced adds a paragraph for every attachment the author never
// referenced, in the order they were attached. Each one renders itself, since
// an image appends a markdown embed and a video appends a bare URL so that it
// plays, which is why this half does not live with the rewriting.
func appendUnreferenced(attachedMD attachedMarkdown, assets []UserAsset) string {
	urlByPath := make(map[string]string, len(attachedMD.ToAppend))
	for _, arg := range attachedMD.ToAppend {
		urlByPath[arg.Path] = arg.URL
	}

	out := attachedMD.Rewritten
	for _, a := range assets {
		url, ok := urlByPath[a.Path()]
		if !ok {
			continue
		}
		out = appendParagraph(out, a.markdown(url))
	}
	return out
}

// applyEdits rewrites the markdown back to front, so that an earlier edit cannot
// shift a later one, and reports which arguments were actually written.
//
// Edits overlap when a video embed alone in its paragraph is replaced by a
// bare URL and its alt text carries a reference of its own. The wider edit
// wins, and the dropped one's argument is reported unwritten so the caller
// appends it.
func applyEdits(md string, edits []edit) (string, map[int]bool) {
	written := map[int]bool{}
	if len(edits) == 0 {
		return md, written
	}

	sort.SliceStable(edits, func(i, j int) bool {
		if edits[i].at.start != edits[j].at.start {
			return edits[i].at.start < edits[j].at.start
		}
		return edits[i].at.stop > edits[j].at.stop
	})

	var kept []edit
	end := 0
	for _, e := range edits {
		if e.at.start < end || e.at.start > e.at.stop || e.at.stop > len(md) {
			continue
		}
		kept = append(kept, e)
		written[e.a] = true
		end = e.at.stop
	}

	out := md
	for _, e := range slices.Backward(kept) {
		out = out[:e.at.start] + e.text + out[e.at.stop:]
	}
	return out, written
}

