// literalText reports the byte ranges inside n that a code span quotes, where a
// bracket is a character rather than markdown. goldmark parsed them, so their
// text nodes already say where they are.
func literalText(n ast.Node) []byteRange {
	var out []byteRange
	for c := n.FirstChild(); c != nil; c = c.NextSibling() {
		if _, ok := c.(*ast.CodeSpan); !ok {
			out = append(out, literalText(c)...)
			continue
		}
		for t := c.FirstChild(); t != nil; t = t.NextSibling() {
			if text, ok := t.(*ast.Text); ok {
				out = append(out, byteRange{text.Segment.Start, text.Segment.Stop})
			}
		}
	}
	return out
}

// newAsset validates one attached file.
func newAsset(path, alt string) (UserAsset, error) {
	fi, err := os.Stat(path)
	if err != nil {

		if pathErr, ok := errors.AsType[*fs.PathError](err); ok {
			return nil, fmt.Errorf("%s: %w", path, pathErr.Err)
		}
		return nil, err
	}

	if fi.IsDir() {
		return nil, fmt.Errorf("%s is a directory", path)
	}

	if !fi.Mode().IsRegular() {
		return nil, fmt.Errorf("%s is not a regular file", path)
	}

	if fi.Size() == 0 {
		return nil, fmt.Errorf("%s is empty", path)
	}

	contentType, err := supportedContentType(path)
	if err != nil {
		return nil, err
	}

	f := asset{path: path, info: fi, contentType: contentType}

	if strings.HasPrefix(contentType, "video/") {
		return newVideoAsset(f, alt)
	}
	return newImageAsset(f, alt)
}

// newAttachableDocuments scans every document and refuses what no upload can
// fix, so that nothing uploads for a set of documents that cannot take it.
func newAttachableDocuments(docs []Document, assets []UserAsset) ([]attachableDocument, error) {
	out := make([]attachableDocument, len(docs))
	referenced := make([]bool, len(assets))
	for i, doc := range docs {
		args := newAttachmentArgs(assets)
		md, err := newAttachableMarkdown(doc.Markdown, doc.Dir, args)
		if err != nil {
			return nil, err
		}
		isAttachment := make([]bool, len(assets))
		for _, r := range md.refs {
			isAttachment[r.attachmentArg] = true
			referenced[r.attachmentArg] = true
		}
		out[i] = attachableDocument{md: md, args: args, isAttachment: isAttachment}
	}

	if len(docs) == 1 {

		for i := range out[0].isAttachment {
			out[0].isAttachment[i] = true
		}
		return out, nil
	}

	var unreferenced []string
	for i, a := range assets {
		if !referenced[i] {
			unreferenced = append(unreferenced, a.Path())
		}
	}
	if len(unreferenced) > 0 {
		return nil, &UnreferencedError{Paths: unreferenced}
	}
	return out, nil
}

// newAttachableMarkdown scans markdown for the files it references, and
// refuses references that no asset URL can fix.
func newAttachableMarkdown(md, markdownDir string, attachmentArgs []attachmentArg) (attachableMarkdown, error) {
	if len(attachmentArgs) == 0 {
		return attachableMarkdown{markdown: md}, nil
	}
	refs, err := scanMarkdownRefs(md, markdownDir, attachmentArgs)
	if err != nil {
		return attachableMarkdown{}, err
	}
	if err := checkVideoReferenceImages(refs, attachmentArgs); err != nil {
		return attachableMarkdown{}, err
	}
	return attachableMarkdown{markdown: md, refs: refs, args: attachmentArgs}, nil
}

// newAttachmentArgs describes each asset for the markdown half of the
// package, without a URL, since nothing has uploaded yet.
func newAttachmentArgs(assets []UserAsset) []attachmentArg {
	args := make([]attachmentArg, len(assets))
	for i, a := range assets {
		f := a.getAsset()
		args[i] = attachmentArg{Path: f.path, Alt: f.alt, RendersAsPlayer: a.rendersAsPlayer()}
	}
	return args
}

// newImageAsset applies what only holds for an image: the author may write alt
// text, and the fallback mirrors the web uploader by stripping the extension
// and replacing the remaining dots with spaces.
func newImageAsset(f asset, alt string) (UserAsset, error) {
	a := &imageAsset{f}
	if err := checkMaxSize(a.asset, maxImageBytes, "images"); err != nil {
		return nil, err
	}

	if alt == "" {
		base := filepath.Base(a.path)
		alt = strings.ReplaceAll(strings.TrimSuffix(base, filepath.Ext(base)), ".", " ")
	}
	a.alt = alt

	if err := checkAltStaysInside(a); err != nil {
		return nil, err
	}

	return a, nil
}

// newUploadError captures the status code so the message can name what the
// endpoint refused.
func newUploadError(err error, a UserAsset) error {
	uploadErr := &uploadError{Path: a.Path(), err: err}
	if httpError, ok := errors.AsType[api.HTTPError](err); ok {
		uploadErr.StatusCode = httpError.StatusCode
		uploadErr.Message = httpError.Message
		uploadErr.RetryAfter = httpError.Headers.Get("Retry-After")
	}
	return uploadErr
}

// newVideoAsset applies what only holds for a video: a player has no alt
// attribute to fill, so the author cannot supply one, and the name that stands
// in keeps its extension because it goes where a filename would in a link.
func newVideoAsset(f asset, alt string) (UserAsset, error) {
	a := &videoAsset{f}
	if err := checkMaxSize(a.asset, maxVideoBytes, "videos"); err != nil {
		return nil, err
	}

	if alt != "" {
		return nil, errors.New("cannot set alt text on video")
	}
	a.alt = filepath.Base(a.path)

	return a, nil
}

// scanAngleDest reads a "<...>" destination beginning at the "<", returning the
// index just past the closing ">".
func scanAngleDest(src []byte, i, hi int) (int, bool) {
	i++
	for i < hi && src[i] != '>' && src[i] != '\n' {
		if src[i] == '\\' && i+1 < hi {
			i++
		}
		i++
	}
	if i >= hi || src[i] != '>' {
		return 0, false
	}
	return i + 1, true
}

// scanBareDest reads an unbracketed destination, which ends at whitespace or
// at the ")" closing the link. Parentheses inside the path are part of it as
// long as they balance.
func scanBareDest(src []byte, i, hi int) int {
	depth := 0
	for i < hi {
		switch c := src[i]; {
		case c == '\\':
			if i+1 < hi {
				i++
			}
		case isSpace(c):
			return i
		case c == '(':
			depth++
		case c == ')':
			if depth == 0 {
				return i
			}
			depth--
		}
		i++
	}
	return i
}

