// scanTitle skips the optional title following a destination and returns the
// index just past it. i may point at anything: a byte that opens no title
// leaves the index untouched. A title is delimited by double quotes, single
// quotes, or parentheses.
func scanTitle(src []byte, i, hi int) (int, bool) {
	var closer byte
	switch src[i] {
	case '"', '\'':
		closer = src[i]
	case '(':
		closer = ')'
	default:
		return i, true
	}
	i++
	for i < hi && src[i] != closer {
		if src[i] == '\\' && i+1 < hi {
			i++
		}
		i++
	}
	if i >= hi {
		return 0, false
	}
	return i + 1, true
}

func skipSpace(src []byte, i, hi int) int {
	for i < hi && isSpace(src[i]) {
		i++
	}
	return i
}

// standsAlone reports whether replacing a node with a bare URL will render as
// a player.
//
// GitHub promotes a bare asset URL to a video exactly when it is the whole
// content of a paragraph, wherever that paragraph sits: a blockquote or a
// loose list item qualifies, a URL alone on a source line inside a wrapped
// paragraph does not. A tight list item holds no paragraph, only a text
// block, which is why a lone reference there stays a link. goldmark draws the
// same distinction, so testing for a paragraph is the whole rule.
func standsAlone(src []byte, block ast.Node, node byteRange) bool {
	if _, ok := block.(*ast.Paragraph); !ok {
		return false
	}
	lo, hi, ok := blockRange(block, len(src))

	if !ok || node.start < lo || node.stop > hi {
		return false
	}
	for _, c := range src[lo:node.start] {
		if !isSpace(c) {
			return false
		}
	}
	for _, c := range src[node.stop:hi] {
		if !isSpace(c) {
			return false
		}
	}
	return true
}

// supportedContentType maps a file extension to the content type the endpoint
// expects. The extension is all gh checks, since the endpoint accepts
// mislabeled bytes anyway.
func supportedContentType(path string) (string, error) {
	ext := strings.ToLower(filepath.Ext(path))
	for _, t := range contentTypes {
		if t.ext == ext {
			return t.contentType, nil
		}
	}

	supported := make([]string, len(contentTypes))
	for i, t := range contentTypes {
		supported[i] = strings.TrimPrefix(t.ext, ".")
	}
	return "", fmt.Errorf("%s is not a supported file type (supported: %s)", path, strings.Join(supported, ", "))
}

func trimAngles(s string) string {
	if len(s) >= 2 && s[0] == '<' && s[len(s)-1] == '>' {
		return s[1 : len(s)-1]
	}
	return s
}

// unescapePunctuation drops the backslash from every backslash-escaped ASCII
// punctuation character, which is how markdown spells a literal one.
func unescapePunctuation(s string) string {
	if !strings.Contains(s, `\`) {
		return s
	}
	const punct = `!"#$%&'()*+,-./:;<=>?@[\]^_` + "`" + `{|}~`
	var b strings.Builder
	b.Grow(len(s))
	for i := 0; i < len(s); {
		if s[i] == '\\' && i+1 < len(s) && strings.IndexByte(punct, s[i+1]) >= 0 {
			i++
		}
		b.WriteByte(s[i])
		i++
	}
	return b.String()
}

func (e *uploadError) Error() string {
	switch e.StatusCode {
	case http.StatusNotFound:

		return fmt.Sprintf("could not upload %s: attaching files requires write access to the repository", e.Path)
	case http.StatusUnprocessableEntity:
		if e.Message == "" {
			return fmt.Sprintf("could not upload %s", e.Path)
		}
		return fmt.Sprintf("could not upload %s: %s", e.Path, strings.ReplaceAll(e.Message, "\n", "; "))
	case http.StatusTooManyRequests:
		if e.RetryAfter == "" {
			return fmt.Sprintf("could not upload %s: rate limited; wait and try again", e.Path)
		}
		retryAfter := e.RetryAfter
		if seconds, err := strconv.Atoi(e.RetryAfter); err == nil {
			retryAfter = fmt.Sprintf("%d seconds", seconds)
		}
		return fmt.Sprintf("could not upload %s: rate limited; retry after %s", e.Path, retryAfter)
	}
	return fmt.Sprintf("failed to upload %s: %v", e.Path, e.err)
}

func (e *uploadError) Unwrap() error {
	return e.err
}

func uploadMatcher(repositoryID int64, name string) httpmock.Matcher {
	return httpmock.QueryMatcher("POST", "user-attachments/assets", url.Values{
		"repository_id":	[]string{strconv.FormatInt(repositoryID, 10)},
		"name":			[]string{name},
	})
}

func userAssetsFromArgs(args []string) ([]UserAsset, error) {

	if len(args) == 0 {
		return nil, errEmptyPath
	}

	resolvedAssets := make([]UserAsset, 0, len(args))
	for _, arg := range args {
		a, err := assetFromArg(arg)
		if err != nil {
			return nil, err
		}

