		cfg, err := f.Config()
		if err != nil {

			apiURL = defaultAPIURL
		} else {
			host, _ := cfg.Authentication().DefaultHost()
			apiURL = ghinstance.RESTPrefix(host)
		}
	}

	serverURL := os.Getenv("GITHUB_SERVER_URL")
	if serverURL == "" {
		cfg, err := f.Config()
		if err != nil {

			serverURL = defaultServerURL
		} else {
			host, _ := cfg.Authentication().DefaultHost()
			serverURL = ghinstance.HostPrefix(host)
		}
	}

