	ch := make(chan error, 1)
	go func() {
		defer close(ch)
		ch <- keyring.Set(service, user, secret)
	}()
	select {
	case err := <-ch:
		return err
	case <-time.After(60 * time.Second):
		return &TimeoutError{"timeout while trying to set secret in keyring"}
	}
}

