func cloneEvent(event ghtelemetry.Event) ghtelemetry.Event {
	return ghtelemetry.Event{
		Type:		event.Type,
		Dimensions:	maps.Clone(event.Dimensions),
		Measures:	maps.Clone(event.Measures),
	}
