// NewCAPIClient creates a new CAPI client. Provide a token, the user's GitHub
// host, the resolved Copilot API URL, and an HTTP client which will be used as
// the base transport for CAPI requests.
//
// The provided HTTP client will be mutated for use with CAPI, so it should not
// be reused elsewhere.
func NewCAPIClient(httpClient *http.Client, token string, host string, capiBaseURL string) *CAPIClient {
	httpClient.Transport = newCAPITransport(token, capiBaseURL, httpClient.Transport)
	return &CAPIClient{
		httpClient:	httpClient,
		host:		host,
		capiBaseURL:	capiBaseURL,
	}
}

// ExportData implements the exportable interface for JSON output.
func (s *Session) ExportData(fields []string) map[string]any {
	data := make(map[string]any, len(fields))
	for _, f := range fields {
		switch f {
		case "id":
			data[f] = s.ID
		case "name":
			data[f] = s.Name
		case "state":
			data[f] = s.State
		case "repository":
			if s.PullRequest != nil && s.PullRequest.Repository != nil {
				data[f] = s.PullRequest.Repository.NameWithOwner
			} else {
				data[f] = nil
			}
		case "user":
			if s.User != nil {
				data[f] = s.User.Login
			} else {
				data[f] = nil
			}
		case "createdAt":
			if s.CreatedAt.IsZero() {
				data[f] = nil
			} else {
				data[f] = s.CreatedAt
			}
		case "updatedAt":
