func (w *jsonArrayWriter) Close() error {
	var delims string
	if w.started {
		delims = "]"
	} else {
		delims = "[]"
	}

	w.started = false
	if w.color {
		return jsoncolor.WriteDelims(w, delims, ttyIndent)
	}

	_, err := w.Writer.Write([]byte(delims))
	return err
}

func (w *jsonArrayWriter) Preface() []json.Delim {
	if w.started {
		return []json.Delim{'['}
	}
	return nil
}

// ReadFrom implements io.ReaderFrom to write more data than read,
// which otherwise results in an error from io.Copy().
func (w *jsonArrayWriter) ReadFrom(r io.Reader) (int64, error) {
	var written int64
	buf := make([]byte, 4069)
	for {
		n, err := r.Read(buf)
		if n > 0 {
			n, err := w.Write(buf[:n])
			written += int64(n)

			if err != nil {
				return written, err
			}
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			return written, err
		}
	}

	return written, nil
}

