}

// GetCurrentLogin returns the login of the user the token belongs to.
//
// The token is passed explicitly because this runs before the token is stored in config, so
// the transport has nothing to attach. The transport only sets Authorization when it is
// absent, so the header set here wins.
func GetCurrentLogin(httpClient *http.Client, hostname, authToken string) (string, error) {
	var result struct{ Viewer struct{ Login string } }

	err := api.NewClientFromHTTP(httpClient).GraphQL(hostname, `query UserCurrent{viewer{login}}`, nil, &result,
		api.WithHeader("Authorization", "token "+authToken))
	if err != nil {
		return "", err
	}
	return result.Viewer.Login, nil
}

// GetScopes performs a GitHub API request and returns the value of the X-Oauth-Scopes header.
//
// The token is passed explicitly because this runs before the token is stored in config, so
// the transport has nothing to attach. The transport only sets Authorization when it is
// absent, so the header set here wins.
func GetScopes(httpClient *http.Client, hostname, authToken string) (string, error) {

	res, err := api.NewClientFromHTTP(httpClient).Request(hostname, http.MethodGet, safeurl.NewImmutableSafeURL("").String(), nil,
		api.WithHeader("Authorization", "token "+authToken))
	if err != nil {
		return "", err
	}

	defer func() {

		_, _ = io.Copy(io.Discard, res.Body)
		res.Body.Close()
	}()

	if res.StatusCode != 200 {
		return "", api.UnexpectedStatusError(res)
	}

	return res.Header.Get("X-Oauth-Scopes"), nil
}

func (flow *GitCredentialFlow) Prompt(hostname string) error {
	// First we'll fetch the credential helper that would be used for this host
	var configuredHelperErr error
	flow.helper, configuredHelperErr = flow.HelperConfig.ConfiguredHelper(hostname)

	if flow.helper.IsOurs() {
		flow.scopes = append(flow.scopes, "workflow")
		return nil
	}

	result, err := flow.Prompter.Confirm("Authenticate Git with your GitHub credentials?", true)
	if err != nil {
		return err
	}
	flow.shouldSetup = result

	if flow.shouldSetup {

		if _, ok := errors.AsType[*git.NotInstalled](configuredHelperErr); ok {
			return configuredHelperErr
		}

		flow.scopes = append(flow.scopes, "workflow")
	}

	return nil
}

