// DiscussionClientFunc returns a factory function that creates a DiscussionClient
// from the given Factory. The returned function is intended to be stored in
// command Options structs and called lazily inside RunE.
func DiscussionClientFunc(f *cmdutil.Factory) func() (client.DiscussionClient, error) {
	return func() (client.DiscussionClient, error) {
		httpClient, err := f.HttpClient()
		if err != nil {
			return nil, err
		}
		return client.NewDiscussionClient(httpClient), nil
	}
}

// MatchCategory finds a category by name or slug (case-insensitive).
// It prefers an exact slug match over a name match, so users are
// encouraged to use slugs for unambiguous lookups.
func MatchCategory(input string, categories []client.DiscussionCategory) (*client.DiscussionCategory, error) {
	for i := range categories {
		if strings.EqualFold(categories[i].Slug, input) {
			return &categories[i], nil
		}
	}
	for i := range categories {
		if strings.EqualFold(categories[i].Name, input) {
			return &categories[i], nil
		}
	}

	slugs := make([]string, len(categories))
	for i, c := range categories {
		slugs[i] = c.Slug
	}
	slices.Sort(slugs)
	return nil, fmt.Errorf("unknown category: %q; must be one of: %s", input, strings.Join(slugs, ", "))
}

// ParseDiscussionArg parses a discussion number or URL from a command argument.
// It returns the discussion number and, if the argument was a URL, a repo override.
func ParseDiscussionArg(arg string) (int32, ghrepo.Interface, error) {
	if num, err := strconv.ParseInt(arg, 10, 32); err == nil {
		return int32(num), nil, nil
	}

	if len(arg) > 1 && arg[0] == '#' {
		if num, err := strconv.ParseInt(arg[1:], 10, 32); err == nil {
			return int32(num), nil, nil
		}
	}

	u, err := url.Parse(arg)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") {
		return 0, nil, fmt.Errorf("invalid discussion argument: %q", arg)
	}

	m := discussionURLRE.FindStringSubmatch(u.Path)
	if m == nil {
		return 0, nil, fmt.Errorf("invalid discussion URL: %q", arg)
	}

	num, err := strconv.ParseInt(m[3], 10, 32)
	if err != nil {
		return 0, nil, fmt.Errorf("invalid discussion number in URL: %q", m[3])
	}

	repo := ghrepo.NewWithHost(m[1], m[2], u.Hostname())
	return int32(num), repo, nil
}

