func (m *browseModel) View() tea.View {
	if m.height > 0 && m.height < 6 {
		content := "terminal too small"
		if m.width > 0 {
			content = ansi.Truncate(content, m.width, "")
		}
		view := tea.NewView(content)
		view.AltScreen = true
		return view
	}

	if m.page == helpPage {
		view := tea.NewView(m.helpView())
		view.AltScreen = true
		return view
	}

	if m.page == readmePage {
		view := tea.NewView(m.readmePaneView())
		view.AltScreen = true
		return view
	}

	var content strings.Builder
	content.WriteString(m.headerView())
	content.WriteByte('\n')
	content.WriteString(m.filterView())
	content.WriteByte('\n')
	content.WriteString(m.mainContent())
	content.WriteByte('\n')
	content.WriteString(m.footerView())

	view := tea.NewView(content.String())
	view.AltScreen = true
	return view
}

func (m *browseModel) applyFilter() bool {
	previous, hadPrevious := m.selectedEntry()
	filter := m.filterInput.Value()
	m.filtered = m.filtered[:0]
	for i, entry := range m.entries {
		searchable := entry.FullName + entry.Description()
		if entry.Official {
			searchable += " official"
		}
		if entry.Installed {
			searchable += " installed"
		}
		if filter == "" || strings.Contains(searchable, filter) {
			m.filtered = append(m.filtered, i)
		}
	}
	m.cursor = 0
	selected, hasSelected := m.selectedEntry()
	return hadPrevious != hasSelected || previous.FullName != selected.FullName
}

func (m *browseModel) filterView() string {
	label := m.colors.Bold("filter:")
	if m.filtering {
		label = m.colors.CyanBold("filter:")
	}
	filter := label + " " + m.filterInput.View()
	if m.width <= 0 {
		return filter
	}
	return renderListLine(filter, m.width)
}

func (m *browseModel) footerView() string {
	var footer string
	switch {
	case m.status != "":
		footer = m.status
	case m.readmeState == readmeLoading:
		footer = "fetching readme..."
	default:
		var (
			full	= fmt.Sprintf(
				"%s help  %s move  %s install  %s remove  %s web  %s view readme  %s quit",
				m.colors.Bold("?"),
				m.colors.Bold("j/k"),
				m.colors.Bold("i"),
				m.colors.Bold("r"),
				m.colors.Bold("w"),
				m.colors.Bold("enter"),
				m.colors.Bold("q"),
			)
			compact	= fmt.Sprintf(
				"%s help  %s move  %s readme  %s quit",
				m.colors.Bold("?"),
				m.colors.Bold("j/k"),
				m.colors.Bold("enter"),
				m.colors.Bold("q"),
			)
			minimal	= fmt.Sprintf("%s help  %s quit", m.colors.Bold("?"), m.colors.Bold("q"))
		)
		switch {
		case m.width <= 0 || lipgloss.Width(full) <= m.width:
			footer = full
		case lipgloss.Width(compact) <= m.width:
			footer = compact
		default:
			footer = minimal
		}
	}
	if m.width <= 0 {
		return footer
	}
	footer = wrapFooter(footer, m.width)
	if m.height <= 0 {
		return footer
	}
	lines := strings.Split(footer, "\n")
	return strings.Join(lines[:min(len(lines), max(m.height-4, 1))], "\n")
}

func (m *browseModel) headerView() string {
	header := m.colors.Bold(fmt.Sprintf("browsing %d gh extensions", len(m.entries)))
	if m.width <= 0 {
		return header
	}
	return lipgloss.NewStyle().
		Width(m.width).
		Align(lipgloss.Center).
		Render(header)
}

func (m *browseModel) helpView() string {
	lines := strings.Split(helpText, "\n")
	for i, line := range lines {
		switch line {
		case "Application", "Navigation", "Extension Management", "Filtering", "Readmes":
			lines[i] = m.colors.Bold(line)
		default:
			key, description, ok := strings.Cut(line, ":")
			if ok && key != "" {
				lines[i] = m.colors.Bold(key) + ":" + description
			}
		}
	}
	return strings.Join(lines, "\n")
}

func (m *browseModel) listView() string {
	if len(m.filtered) == 0 {
		return "no matching extensions"
	}

	lines := make([]string, 0, m.pageSize()*2)
	pageSize := m.pageSize()
	start := min((m.cursor/pageSize)*pageSize, max(len(m.filtered)-pageSize, 0))
	end := min(start+pageSize, len(m.filtered))
	for i := start; i < end; i++ {
		entry := m.entries[m.filtered[i]]
		prefix := "  "
		if i == m.cursor {
			prefix = "> "
		}
		title := prefix + entry.FullName
		switch {
		case i == m.cursor:
			if entry.Official {
				title += " (official)"
			}
			if entry.Installed {
				title += " (installed)"
			}
			title = lipgloss.NewStyle().Reverse(true).Render(title)
		default:
			title = m.colors.Bold(title)
			if entry.Official {
				title += " " + m.colors.Yellow("(official)")
			}
			if entry.Installed {
				title += " " + m.colors.Green("(installed)")
			}
		}
		lines = append(lines,
			renderListLine(title, m.listWidth()),
			renderListLine("  "+entry.Description(), m.listWidth()),
		)
	}

	return strings.Join(lines, "\n")
}

func (m *browseModel) listWidth() int {
	if m.singleColumn() || m.width <= 0 {
		return m.width
	}
	return max(m.width/2, 1)
}

func (m *browseModel) loadSelectedReadme() tea.Cmd {
	selected, ok := m.selectedEntry()
	if !ok {
		m.readmeName = ""
		m.readmeRaw = ""
		m.readmeState = readmeIdle
		m.readme.SetContent("")
		return nil
	}
	if m.opts.Rg == nil {
		return nil
	}
	m.readmeName = selected.FullName
	m.readmeRaw = ""
	m.readmeState = readmeLoading
	m.readme.SetContent("fetching readme...")

	fullName := selected.FullName
	loader := m.opts.Rg
	renderer := m.opts.renderReadme
	width := m.readmeWidth()
	return func() tea.Msg {
		raw, err := loader.Get(fullName)
		if err != nil {
			return readmeLoadedMsg{fullName: fullName, err: err}
		}
		rendered, err := renderer(raw, width)
		return readmeLoadedMsg{fullName: fullName, raw: raw, rendered: rendered, width: width, err: err}
	}
}

func (m *browseModel) mainContent() string {
	list := lipgloss.NewStyle().
		Width(m.listWidth()).
		Height(m.mainHeight()).
		Render(m.listView())
	if m.singleColumn() {
		return list
	}
	return lipgloss.JoinHorizontal(lipgloss.Top, list, m.readmePaneView())
}

func (m *browseModel) mainHeight() int {
	footerHeight := strings.Count(m.footerView(), "\n") + 1
	return max(m.height-3-footerHeight, 1)
}

func (m *browseModel) moveByPage(direction int) tea.Cmd {
	if len(m.filtered) == 0 {
		return nil
	}
	m.cursor = min(max(m.cursor+direction*m.pageSize(), 0), len(m.filtered)-1)
	return m.loadSelectedReadme()
}

func (m *browseModel) pageSize() int {
	if m.mainHeight() <= 1 {
		return 1
	}
	return max(m.mainHeight()/2, 1)
}

func (m *browseModel) readmePaneView() string {
	style := lipgloss.NewStyle().
		Border(lipgloss.NormalBorder()).
		Width(m.readme.Width() + 2).
		Height(m.readme.Height() + 2)
	if m.colors.Enabled {
		style = style.BorderForeground(lipgloss.Color("5"))
	}
	return style.Render(m.readme.View())
}

func (m *browseModel) readmeWidth() int {
	if m.page == readmePage {
		return max(m.width-2, 1)
	}
	if m.singleColumn() {
		return max(m.width-2, 1)
	}
	return max(m.width-m.listWidth()-2, 1)
}

func (m *browseModel) renderLoadedReadme() tea.Cmd {
	if m.readmeRaw == "" || m.readmeName == "" {
		return nil
	}
	fullName := m.readmeName
	raw := m.readmeRaw
	renderer := m.opts.renderReadme
	width := m.readmeWidth()
	return func() tea.Msg {
		rendered, err := renderer(raw, width)
		return readmeLoadedMsg{fullName: fullName, raw: raw, rendered: rendered, width: width, err: err}
	}
}

func (m *browseModel) resizeFilter() {
	labelWidth := lipgloss.Width("filter: ")
	m.filterInput.SetWidth(max(m.width-labelWidth, 1))
}

func (m *browseModel) resizeReadme() {
	m.readme.SetWidth(m.readmeWidth())
	if m.page == readmePage {
		m.readme.SetHeight(max(m.height-2, 1))
		return
	}
	m.readme.SetHeight(max(m.mainHeight()-2, 1))
}

func (m *browseModel) selectedEntry() (extEntry, bool) {
	if m.cursor < 0 || m.cursor >= len(m.filtered) {
		return extEntry{}, false
	}
	return m.entries[m.filtered[m.cursor]], true
}

func (m *browseModel) setInstalled(fullName string, installed bool) {
	for i := range m.entries {
		if m.entries[i].FullName == fullName {
			m.entries[i].Installed = installed
			return
		}
	}
}

func (m *browseModel) setStatus(status string) {
	m.status = status
	m.resizeReadme()
}

func (m *browseModel) singleColumn() bool {
	return m.opts.SingleColumn || (m.width > 0 && m.width < 100)
}

func (e extEntry) Description() string {
	if e.description == "" {
		return "no description provided"
	}
	return e.description
}

func getExtensions(opts ExtBrowseOpts) ([]extEntry, error) {
	extEntries := []extEntry{}

	installed := opts.Em.List()

	result, err := opts.Searcher.Repositories(search.Query{
		Kind:	search.KindRepositories,
		Limit:	1000,
		Qualifiers: search.Qualifiers{
			Topic: []string{"gh-extension"},
		},
	})
	if err != nil {
		return extEntries, fmt.Errorf("failed to search for extensions: %w", err)
	}

	host, _ := opts.Cfg.Authentication().DefaultHost()

	for _, repo := range result.Items {
		if !strings.HasPrefix(repo.Name, "gh-") {
			continue
		}
		ee := extEntry{
			URL:		"https://" + host + "/" + repo.FullName,
			FullName:	repo.FullName,
			Name:		repo.Name,
			description:	repo.Description,
		}
		for _, installedExtension := range installed {
			var installedRepo string
			if u, err := git.ParseURL(installedExtension.URL()); err == nil {
				if r, err := ghrepo.FromURL(u); err == nil {
					installedRepo = ghrepo.FullName(r)
				}
			}
			if repo.FullName == installedRepo {
				ee.Installed = true
			}
		}
		if repo.Owner.Login == "cli" || repo.Owner.Login == "github" {
			ee.Official = true
		}

		extEntries = append(extEntries, ee)
	}

	return extEntries, nil
}

func newBrowseModel(opts ExtBrowseOpts, entries []extEntry) *browseModel {
	filterInput := textinput.New()
	filterInput.Prompt = ""

	filtered := make([]int, len(entries))
	for i := range entries {
		filtered[i] = i
	}
	if opts.renderReadme == nil {
		opts.renderReadme = renderReadmeMarkdown
	}
	if opts.Logger == nil {
		opts.Logger = log.New(io.Discard, "", 0)
	}
	colors := &iostreams.ColorScheme{}
	if opts.IO != nil {
		colors = opts.IO.ColorScheme()
	}

	model := &browseModel{
		opts:		opts,
		colors:		colors,
		entries:	entries,
		filtered:	filtered,
		filterInput:	filterInput,
		readme:		viewport.New(),
		width:		120,
		height:		30,
	}
	model.resizeReadme()
	return model
}

func newReadmeGetter(client *http.Client, cacheTTL time.Duration) *readmeGetter {
	cachingClient := api.NewCachedHTTPClient(client, cacheTTL)
	return &readmeGetter{
		client: cachingClient,
	}
}

func (g *readmeGetter) Get(repoFullName string) (string, error) {
	repo, err := ghrepo.FromFullName(repoFullName)
	if err != nil {
		return "", err
	}
	readme, err := view.RepositoryReadme(g.client, repo, "")
	if err != nil {
		return "", err
	}
	return readme.Content, nil
}

func renderListLine(line string, width int) string {
	if width <= 0 {
		return line
	}
	line = ansi.Truncate(line, width, "")
	return lipgloss.NewStyle().Width(width).Render(line)
}

func renderReadmeMarkdown(markdown string, width int) (string, error) {
	renderer, err := glamour.NewTermRenderer(
		glamour.WithStylePath("dark"),
		glamour.WithWordWrap(max(width-2, 1)),
	)
	if err != nil {
		return "", err
	}
	return renderer.Render(markdown)
}

func truncateLines(content string, width int) string {
	if width <= 0 {
		return content
	}
	lines := strings.Split(content, "\n")
	for i := range lines {
		lines[i] = ansi.Truncate(lines[i], width, "")
	}
	return strings.Join(lines, "\n")
}

func wrapFooter(footer string, width int) string {
	var wrapped []string
	for line := range strings.SplitSeq(footer, "\n") {
		content := strings.TrimLeft(line, " \t")
		indent := strings.ReplaceAll(line[:len(line)-len(content)], "\t", "    ")
		if content == "" {
			wrapped = append(wrapped, "")
			continue
		}
		for wrappedLine := range strings.SplitSeq(ansi.Hardwrap(content, max(width-len(indent), 1), false), "\n") {
			wrapped = append(wrapped, indent+wrappedLine)
		}
	}
	return strings.Join(wrapped, "\n")
}

// BaseRepoFunc requests a list of Remotes, and selects the first one.
// Although Remotes is injected via the factory so it looks like the function might
// be configurable, in practice, it's calling readRemotes, and the injection is indirection.
//
// readRemotes makes use of the remoteResolver, which is responsible for requesting the list
// of remotes for the current working directory from git. It then does some filtering to
// only retain remotes for hosts that we have authenticated against; keep in mind this may
// be the single value of GH_HOST.
//
// That list of remotes is sorted by their remote name, in the following order:
//  1. upstream
//  2. github
//  3. origin
//  4. other remotes, no ordering guaratanteed because the sort function is not stable
//
// Given that list, this function chooses the first one.
//
// Here's a common example of when this might matter: when we clone a fork, by default we add
// the parent as a remote named upstream. So the remotes may look like this:
// upstream  https://github.com/cli/cli.git (fetch)
// upstream https://github.com/cli/cli.git (push)
// origin  https://github.com/cli/cli-fork.git (fetch)
// origin  https://github.com/cli/cl
// ... (truncated)

func HttpClientFunc(cfgFunc func() (gh.Config, error), ios *iostreams.IOStreams, appVersion string, invokingAgent string, telemetryDisabler ghtelemetry.Disabler) func() (*http.Client, error) {
	return func() (*http.Client, error) {
		cfg, err := cfgFunc()
		if err != nil {
			return nil, err
		}
		opts := api.HTTPClientOptions{
			Config:			cfg.Authentication(),
			Log:			ios.ErrOut,
			LogColorize:		ios.ColorEnabled(),
			AppVersion:		appVersion,
			InvokingAgent:		invokingAgent,
			TelemetryDisabler:	telemetryDisabler,
		}
		client, err := api.NewHTTPClient(opts)
		if err != nil {
			return nil, err
		}
		client.Transport = api.ExtractHeader("X-GitHub-SSO", &ssoHeader)(client.Transport)
		return client, nil
	}
}

// SSOURL returns the URL of a SAML SSO challenge received by the server for clients that use ExtractHeader
// to extract the value of the "X-GitHub-SSO" response header.
func SSOURL() string {
	if ssoHeader == "" {
		return ""
	}
	m := ssoURLRE.FindStringSubmatch(ssoHeader)
	if m == nil {
		return ""
	}
	return m[1]
}

