// SupportsAttachments reports whether an artifact of type artifactType can
// take --attach files. Attachments go in Markdown, which only generic and plan
// artifacts hold, so a type gh learns later supports them only once it's
// added here.
func SupportsAttachments(artifactType string) bool {
	switch artifactType {
	case client.TypeGeneric, client.TypePlan:
		return true
	}
	return false
}

// appendNew appends number to numbers, refusing a number already there.
func appendNew(numbers []int, number int) ([]int, error) {
	if slices.Contains(numbers, number) {
		return nil, fmt.Errorf("duplicate artifact number: %d", number)
	}
	return append(numbers, number), nil
}

// isArtifactURL reports whether arg is meant as an artifact URL: an http(s)
// URL whose path goes on past its issue number. parseArtifactURL decides
// whether it's a valid one.
func isArtifactURL(arg string) bool {
	u, err := url.Parse(arg)
	return err == nil && (u.Scheme == "http" || u.Scheme == "https") && pastIssuePath.MatchString(u.Path)
}

// parseArtifactURL reads an artifact URL into its repository, issue number
// and artifact number. Like an issue URL, it may be http, and its query and
// fragment are ignored: only those three are read from it, and requests go to
// the API.
func parseArtifactURL(arg string) (ghrepo.Interface, int, int, error) {
	invalid := fmt.Errorf("invalid artifact URL: %q", arg)
	u, err := url.Parse(arg)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Hostname() == "" {
		return nil, 0, 0, invalid
	}
	m := artifactURLPath.FindStringSubmatch(u.Path)
	if m == nil {
		return nil, 0, 0, invalid
	}
	issueNumber, err := strconv.Atoi(m[3])
	if err != nil || issueNumber < 1 {
		return nil, 0, 0, invalid
	}
	number, err := strconv.Atoi(m[4])
	if err != nil || number < 1 {
		return nil, 0, 0, invalid
	}
	return ghrepo.NewWithHost(m[1], m[2], u.Hostname()), issueNumber, number, nil
}

// parseArtifactURLs reads every argument as an artifact URL on the same
// issue.
func parseArtifactURLs(args []string) (int, func() (ghrepo.Interface, error), []int, error) {
	var repo ghrepo.Interface
	var issueNumber int
	numbers := make([]int, 0, len(args))
	for _, arg := range args {
		r, issue, number, err := parseArtifactURL(arg)
		if err != nil {
			return 0, nil, nil, err
		}
		if repo == nil {
			repo, issueNumber = r, issue
		} else if issue != issueNumber || !ghrepo.IsSame(r, repo) {
			return 0, nil, nil, errors.New("artifact URLs must all be on the same issue")
		}
		if numbers, err = appendNew(numbers, number); err != nil {
			return 0, nil, nil, err
		}
	}
	return issueNumber, func() (ghrepo.Interface, error) { return repo, nil }, numbers, nil
}

// printResultLine prints a piped result line. Every line has all five
// tab-separated columns, even empty ones, like gh pr checks rows.
func printResultLine(w io.Writer, status string, r Result, reason string) {
	var number string
	if r.Number > 0 {
		number = strconv.Itoa(r.Number)
	}
	fmt.Fprintf(w, "%s\t%s\t%s\t%s\t%s\n", status, number, r.Name, r.Source, reason)
}

func pullRequestError(repo ghrepo.Interface, number int) error {
	return fmt.Errorf("%s#%d is a pull request; artifacts are only supported on issues", ghrepo.FullName(repo), number)
}

// displayName returns a user's login for the terminal. A null user shows as
// ghost, like a deleted user in gh pr view, so callers use it only when the
// user's action has a time.
func displayName(u *client.Actor) string {
	if u == nil {
		return "ghost"
	}
	return u.Login
}

// login returns a user's login, or an empty string for a null user.
func login(u *client.Actor) string {
	if u == nil {
		return ""
	}
	return u.Login
}

// metadataLine describes the artifact under its name: its number, type,
// creator and last editor, or for an earlier version, that version's number
// and who saved it. A part whose time is null is left out, and so is the
// update of an artifact that was never edited.
func metadataLine(a client.Artifact, viewing *client.Version, now time.Time) string {
	parts := []string{fmt.Sprintf("Artifact %d", a.Number), a.Type}

	if viewing != nil {
		parts = append(parts, fmt.Sprintf("Version %d", viewing.Version))
		if viewing.CreatedAt != nil {
			action := "updated"
			if viewing.Version == 1 {
				action = "created"
			}
			parts = append(parts, fmt.Sprintf("%s %s %s", displayName(viewing.Actor), action, text.FuzzyAgo(now, *viewing.CreatedAt)))
		}
		return strings.Join(parts, " • ")
	}

	if a.CreatedAt != nil {
		parts = append(parts, fmt.Sprintf("%s created %s", displayName(a.Creator), text.FuzzyAgo(now, *a.CreatedAt)))
	}
	if a.UpdatedAt != nil && (a.CreatedAt == nil || !a.UpdatedAt.Equal(*a.CreatedAt)) {
		parts = append(parts, fmt.Sprintf("%s updated %s", displayName(a.UpdatedByActor), text.FuzzyAgo(now, *a.UpdatedAt)))
	}
	return strings.Join(parts, " • ")
}

// openInBrowser opens a document's page on GitHub, or a link's URL. The page
// comes from the API, so the message shows it like gh issue view --web does.
// A link's URL is anything its author saved, so only an http(s) URL opens,
// and the message shows the whole URL, where text.DisplayURL would hide its
// port, query and fragment.
func openInBrowser(opts *ViewOptions, a client.Artifact) error {
	target, shown := a.URL, text.DisplayURL(a.URL)
	if a.Type == client.TypeLink {
		u, ok := shared.HTTPURL(a.Body)
		if !ok {
			return fmt.Errorf("artifact %d doesn't link to an http(s) URL; `--web` only opens http(s) URLs", a.Number)
		}
		target, shown = u, u
	}

	if opts.IO.IsStdoutTTY() {
		fmt.Fprintf(opts.IO.ErrOut, "Opening %s in your browser.\n", shown)
	}
	return opts.Browser.Browse(target)
}

// printEditHistory lists every version the API returned, newest first, with
// who saved it and when. "Current" marks the newest version, and "Viewing"
// marks the earlier version shown.
func printEditHistory(ios *iostreams.IOStreams, now time.Time, versions []client.Version, viewing *client.Version) error {
	cs := ios.ColorScheme()

	tp := tableprinter.New(ios, tableprinter.NoHeader)
	for i, v := range versions {
		tp.AddField(strconv.Itoa(v.Version))
		if v.CreatedAt != nil {
			tp.AddField(displayName(v.Actor))
			tp.AddTimeField(now, *v.CreatedAt, cs.Muted)
		} else {
			tp.AddField(login(v.Actor))
			tp.AddField("")
		}
		switch {
		case i == 0:
			tp.AddField("Current", tableprinter.WithColor(cs.CyanBold))
		case viewing != nil && v.Version == viewing.Version:
			tp.AddField("Viewing", tableprinter.WithColor(cs.CyanBold))
		}
		tp.EndRow()
	}
	return tp.Render()
}

