func RequestableReviewersForCompletion(httpClient *http.Client, repo ghrepo.Interface) ([]string, error) {
	client := api.NewClientFromHTTP(api.NewCachedHTTPClient(httpClient, time.Minute*2))

	metadata, err := api.RepoMetadata(client, repo, api.RepoMetadataInput{
		Reviewers:	true,
		TeamReviewers:	true,
	})
	if err != nil {
		return nil, err
	}

	results := []string{}
	for _, user := range metadata.AssignableUsers {
		if strings.EqualFold(user.Login(), metadata.CurrentLogin) {
			continue
		}
		if user.Name() != "" {
			results = append(results, fmt.Sprintf("%s\t%s", user.Login(), user.Name()))
		} else {
			results = append(results, user.Login())
		}
	}
	for _, team := range metadata.Teams {
		results = append(results, fmt.Sprintf("%s/%s", repo.RepoOwner(), team.Slug))
	}

	sort.Strings(results)
	return results, nil
}

// ResolveWorktreeTarget validates path and determines whether it is the root
// of an existing linked worktree for the current repository.
func ResolveWorktreeTarget(client *git.Client, path string) (WorktreeTarget, error) {
	target := WorktreeTarget{Path: path}
	if err := ensureWorktreePathSafe(path); err != nil {
		return target, err
	}

	reuse, err := resolveWorktreeTarget(client, path)
	if err != nil {
		return target, err
	}
	if !reuse {
		if err := ensureWorktreePathEmpty(path); err != nil {
			return target, err
		}
	}
	target.Reuse = reuse
	return target, nil
}

func SearchQueryBuild(options FilterOptions, advancedIssueSearchSyntax bool) string {
	var is, state string
	switch options.State {
	case "open", "closed":
		state = options.State
	case "merged":
		is = "merged"
	}

	query := search.Query{
		Qualifiers: search.Qualifiers{
			Assignee:	options.Assignee,
			Author:		options.Author,
			Base:		options.BaseBranch,
			Draft:		options.Draft,
			Head:		options.HeadBranch,
			IssueType:	options.IssueType,
			Label:		options.Labels,
			Mentions:	options.Mention,
			Milestone:	options.Milestone,
			Repo:		[]string{options.Repo},
			State:		state,
			Is:		[]string{is},
			Type:		options.Entity,
		},
		ImmutableKeywords:	options.Search,
	}

	if !advancedIssueSearchSyntax {
		return query.StandardSearchString()
	}
	return query.AdvancedIssueSearchString()
}

