func WithPrAndIssueQueryParams(client *api.Client, baseRepo ghrepo.Interface, baseURL string, state IssueMetadataState, projectsV1Support gh.ProjectsV1Support) (string, error) {
	u, err := url.Parse(baseURL)
	if err != nil {
		return "", err
	}
	q := u.Query()
	if state.Title != "" {
		q.Set("title", state.Title)
	}

	q.Set("body", state.Body)
	if len(state.Assignees) > 0 {
		q.Set("assignees", strings.Join(state.Assignees, ","))
	}

	if len(state.Template) > 0 && len(state.Body) == 0 {
		q.Set("template", state.Template)
	}
	if len(state.Labels) > 0 {
		q.Set("labels", strings.Join(state.Labels, ","))
	}
	if len(state.ProjectTitles) > 0 {
		projectPaths, err := api.ProjectTitlesToPaths(client, baseRepo, state.ProjectTitles, projectsV1Support)
		if err != nil {
			return "", fmt.Errorf("could not add to project: %w", err)
		}
		q.Set("projects", strings.Join(projectPaths, ","))
	}
	if len(state.Milestones) > 0 {
		q.Set("milestone", state.Milestones[0])
	}

	u.RawQuery = q.Encode()
	return u.String(), nil
}

// WorktreeCheckoutCommands returns the commands needed to place branch in
// target. startPoint must be a remote branch suitable for --track.
func WorktreeCheckoutCommands(client *git.Client, target WorktreeTarget, branch, startPoint string) ([][]string, bool) {
	branchExists := client.HasLocalBranch(context.Background(), branch)

	if target.Reuse {
		if branchExists {
			return [][]string{{"-C", target.Path, "checkout", branch}}, true
		}
		return [][]string{{"-C", target.Path, "checkout", "-b", branch, "--track", startPoint}}, false
	}

	if branchExists {
		return [][]string{{"worktree", "add", "--", target.Path, branch}}, true
	}
	return [][]string{{"worktree", "add", "--track", "-b", branch, "--", target.Path, startPoint}}, false
}

