// bodyForWrite uploads the assets and reports whether the body it produced is
// worth writing. A failed upload that produced nothing writes nothing, since
// there is nothing to salvage and a comment that promises an attachment it
// does not have only compounds the failure.
//
// Callers must call this after every prompt, since nothing that can prompt or
// cancel may follow an upload.
func bodyForWrite(opts *CommentableOptions, uploader *attachments.Uploader) (body string, write bool, err error) {
	if uploader == nil {
		return opts.Body, true, nil
	}
	body, uploadResult, err := uploader.UploadAndAttach(context.Background(), opts.Body, opts.BodyDir, opts.Assets)
	opts.AttachEvent.RecordOperations(uploadResult)
	if err != nil && uploadResult.Uploaded == 0 {
		return "", false, err
	}
	return body, true, err
}

func confirmSubmission(p Prompt, allowPreview, allowMetadata, allowDraft, isDraft bool) (Action, error) {
	var options []string
	if !isDraft {
		options = append(options, submitLabel)
	}
	if allowDraft {
		options = append(options, submitDraftLabel)
	}
	if allowPreview {
		options = append(options, previewLabel)
	}
	if allowMetadata {
		options = append(options, metadataLabel)
	}
	options = append(options, cancelLabel)

	result, err := p.Select("What's next?", "", options)
	if err != nil {
		return -1, fmt.Errorf("could not prompt: %w", err)
	}

	switch options[result] {
	case submitLabel:
		return SubmitAction, nil
	case submitDraftLabel:
		return SubmitDraftAction, nil
	case previewLabel:
		return PreviewAction, nil
	case metadataLabel:
		return MetadataAction, nil
	case cancelLabel:
		return CancelAction, nil
	default:
		return -1, fmt.Errorf("invalid index: %d", result)
	}
}

