func runEditItem(config editItemConfig) error {

	if config.opts.url != "" || config.opts.field != "" {
		resolved, err := resolveItemEditNames(config)
		if err != nil {
			return err
		}
		config = resolved
	}

	if config.opts.clear {
		return clearItemFieldValue(config)
	}

	if config.opts.titleChanged || config.opts.bodyChanged {
		return updateDraftIssue(config)
	}

	if config.opts.text != "" || config.opts.numberChanged || config.opts.date != "" || config.opts.singleSelectOptionID != "" || config.opts.iterationID != "" {
		return updateItemValues(config)
	}

	if _, err := fmt.Fprintln(config.io.ErrOut, "error: no changes to make"); err != nil {
		return err
	}
	return cmdutil.SilentError
}

func updateDraftIssue(config editItemConfig) error {
	if !strings.HasPrefix(config.opts.itemID, "DI_") {
		return cmdutil.FlagErrorf("ID must be the ID of the draft issue content which is prefixed with `DI_`")
	}

	// Fetch current draft issue to preserve fields that aren't being updated
	var currentDraftIssue *queries.DraftIssue
	var err error
	if !config.opts.titleChanged || !config.opts.bodyChanged {
		currentDraftIssue, err = fetchDraftIssueByID(config, config.opts.itemID)
		if err != nil {
			return err
		}
	}

	query, variables := buildEditDraftIssue(config, currentDraftIssue)

	err = config.client.Mutate("EditDraftIssueItem", query, variables)
	if err != nil {
		return err
	}

	if config.opts.exporter != nil {
		return config.opts.exporter.Write(config.io, query.UpdateProjectV2DraftIssue.DraftIssue)
	}

	return printDraftIssueResults(config, query.UpdateProjectV2DraftIssue.DraftIssue)
}

func updateItemValues(config editItemConfig) error {
	if err := fieldIdAndProjectIdPresence(config); err != nil {
		return err
	}

	var parsedDate time.Time
	if config.opts.date != "" {
		date, err := time.Parse("2006-01-02", config.opts.date)
		if err != nil {
			return err
		}
		parsedDate = date
	}

	query, variables := buildUpdateItem(config, parsedDate)
	err := config.client.Mutate("UpdateItemValues", query, variables)
	if err != nil {
		return err
	}

	if config.opts.exporter != nil {
		return config.opts.exporter.Write(config.io, &query.Update.Item)
	}

	return printItemResults(config, &query.Update.Item)
}

// fieldValueForItem returns the display value of the field identified by fieldID
// on item i, or an empty string when the item has no value for that field.
func fieldValueForItem(i queries.ProjectItem, fieldID string) string {
	for _, v := range i.FieldValues.Nodes {
		if v.ID() == fieldID {
			return v.DisplayValue()
		}
	}
	return ""
}

func printResults(config listConfig, items []queries.ProjectItem, login string, extraFields []fieldColumn) error {
	if len(items) == 0 {
		return cmdutil.NewNoResultsError(fmt.Sprintf("Project %d for owner %s has no items", config.opts.number, login))
	}

	headers := []string{"Type", "Title", "Number", "Repository", "ID"}
	for _, f := range extraFields {
		headers = append(headers, f.Header)
	}

	tp := tableprinter.New(config.io, tableprinter.WithHeader(headers...))

	for _, i := range items {
		tp.AddField(i.Type())
		tp.AddField(i.Title())
		if i.Number() == 0 {
			tp.AddField("")
		} else {
			tp.AddField(strconv.Itoa(i.Number()))
		}
		tp.AddField(i.Repo())
		tp.AddField(i.ID(), tableprinter.WithTruncate(nil))
		for _, f := range extraFields {
			tp.AddField(fieldValueForItem(i, f.FieldID))
		}
		tp.EndRow()
	}

	return tp.Render()
}

// resolveFieldColumns turns the --field (names) and --field-id (node IDs) flags
// into ordered column descriptors. Names are resolved with ResolveFieldByName so
// unknown or ambiguous names fail with candidate-carrying errors; IDs are
// validated against the project's fields so an unknown ID also fails clearly.
func resolveFieldColumns(opts listOpts, fields []queries.ProjectField) ([]fieldColumn, error) {
	columns := make([]fieldColumn, 0, len(opts.fields)+len(opts.fieldIDs))

	for _, name := range opts.fields {
		field, err := queries.ResolveFieldByName(fields, name)
		if err != nil {
			return nil, err
		}
		columns = append(columns, fieldColumn{Header: field.Name(), FieldID: field.ID()})
	}

	for _, id := range opts.fieldIDs {
		field, err := queries.ResolveFieldByID(fields, id)
		if err != nil {
			return nil, err
		}
		columns = append(columns, fieldColumn{Header: field.Name(), FieldID: field.ID()})
	}

	return columns, nil
}

