func (e *FieldAmbiguousError) Error() string {
	return fmt.Sprintf("field %q is ambiguous; multiple fields share this name (use --field-id with one of: %s)", e.Name, strings.Join(e.Candidates, ", "))
}

func (e *FieldIDNotFoundError) Error() string {
	if len(e.Candidates) == 0 {
		return fmt.Sprintf("field with ID %q not found in project; the project has no fields", e.ID)
	}
	return fmt.Sprintf("field with ID %q not found in project; available fields: %s", e.ID, strings.Join(e.Candidates, ", "))
}

func (e *FieldNotFoundError) Error() string {
	if len(e.Candidates) == 0 {
		return fmt.Sprintf("field %q not found in project; the project has no fields", e.Name)
	}
	return fmt.Sprintf("field %q not found in project; available fields: %s", e.Name, strings.Join(e.Candidates, ", "))
}

// DisplayValue returns a single-line, human-readable rendering of the field
// value suitable for a table cell. Multi-value fields (labels, assignees, etc.)
// are joined with commas, and embedded line breaks are collapsed so a value with
// newlines cannot corrupt table row alignment. It is used by item-list to show a
// named field's value without a separate field-ID preflight lookup.
func (v FieldValueNodes) DisplayValue() string {
	var value string
	switch data := projectFieldValueData(v).(type) {
	case nil:
		return ""
	case string:
		value = data
	case float64:
		value = strconv.FormatFloat(data, 'f', -1, 64)
	case []string:
		value = strings.Join(data, ", ")
	case map[string]any:
		title, _ := data["title"].(string)
		value = title
	default:
		value = fmt.Sprintf("%v", data)
	}
	return singleLineFieldValue(value)
}

