	var matches []ProjectField
	for _, f := range fields {
		if strings.EqualFold(f.Name(), name) {
			matches = append(matches, f)
		}
	}

	switch len(matches) {
	case 1:
		return matches[0], nil
	case 0:
		names := make([]string, 0, len(fields))
		for _, f := range fields {
			names = append(names, f.Name())
