func (w *destinationWriter) check(fp string) error {
	_, err := os.Lstat(fp)
	if err == nil {
		if w.skipExisting {
			return errSkipped
		}
		if !w.overwrite {
			return fmt.Errorf(
				"%s already exists (use `--clobber` to overwrite file or `--skip-existing` to skip file)",
				fp,
			)
		}
	} else if !os.IsNotExist(err) {
		return err
	}
	return nil
}

