			data[field] = e.Path
		case "nameRaw":
			data[field] = e.NameRaw
		case "pathRaw":
			data[field] = e.PathRaw
		case "type":
			data[field] = e.Type
		case "gitType":
			data[field] = e.GitType
		case "mode":
			data[field] = e.Mode
		case "modeOctal":
			data[field] = e.modeOctal()
