func handleUnixDomainSocket(socketPath string) http.RoundTripper {
	if socketPath == "" {
		return http.DefaultTransport
	}

	dialContext := func(ctx context.Context, network, addr string) (net.Conn, error) {
		return (&net.Dialer{}).DialContext(ctx, "unix", socketPath)
	}

	return &http.Transport{
		DialContext:		dialContext,
		DisableKeepAlives:	true,
	}
}

func newCmdSendTelemetry(f *cmdutil.Factory, runF func(*SendTelemetryOptions) error) *cobra.Command {
	cmd := &cobra.Command{
		Use:	"send-telemetry",
		Short:	"Send telemetry event to GitHub",
		Hidden:	true,
		Args:	cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := f.Config()
			if err != nil {
				return err
			}

			payloadJSON, err := io.ReadAll(cmd.InOrStdin())
			if err != nil {
				return fmt.Errorf("reading payload from stdin: %w", err)
			}
			if len(payloadJSON) == 0 {
				return fmt.Errorf("no payload provided on stdin")
			}

			opts := &SendTelemetryOptions{
				TelemetryEndpointURL:	cmp.Or(os.Getenv("GH_TELEMETRY_ENDPOINT_URL"), defaultTelemetryEndpointURL),
				PayloadJSON:		string(payloadJSON),

				HTTPUnixSocket:	cfg.HTTPUnixSocket("").Value,
			}

			if runF != nil {
				return runF(opts)
			}

			return runSendTelemetry(cmd.Context(), opts)
		},
	}

	cmdutil.DisableAuthCheck(cmd)
	cmdutil.DisableTelemetry(cmd)

	return cmd
}

func runSendTelemetry(ctx context.Context, opts *SendTelemetryOptions) error {
	httpClient := &http.Client{
		Timeout:	2 * time.Second,
		Transport: &userAgentTransport{
			base:		handleUnixDomainSocket(opts.HTTPUnixSocket),
			userAgent:	fmt.Sprintf("GitHub CLI %s", build.Version),
		},
	}

	client := observability.NewTelemetryAPIProtobufClient(opts.TelemetryEndpointURL, httpClient)

	var payload telemetry.SendTelemetryPayload
	if err := json.Unmarshal([]byte(opts.PayloadJSON), &payload); err != nil {
		return fmt.Errorf("parsing payload JSON: %w", err)
	}

	if len(payload.Events) == 0 {
		return nil
	}

	events := make([]*observability.TelemetryEvent, len(payload.Events))
	for i, event := range payload.Events {
		events[i] = &observability.TelemetryEvent{
			App:		"github-cli",
			EventType:	event.Type,
			Dimensions:	event.Dimensions,
			Measures:	event.Measures,
		}
	}

	_, err := client.RecordEvents(ctx, &observability.RecordEventsRequest{
		Events: events,
	})
	return err
}

func (t *userAgentTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	req.Header.Set("User-Agent", t.userAgent)
	return t.base.RoundTrip(req)
}

func buildInstallPlans(opts *InstallOptions, selectedSkills []discovery.Skill, selectedHosts []*registry.AgentHost, scope registry.Scope, gitRoot, homeDir string, canPrompt bool) ([]installPlan, error) {
	byDir := make(map[string]*installPlan)
	orderedDirs := make([]string, 0, len(selectedHosts))

	for _, host := range selectedHosts {
		targetDir, err := resolveInstallDir(opts, host, scope, gitRoot, homeDir)
		if err != nil {
			return nil, err
		}

		plan, ok := byDir[targetDir]
		if !ok {
			plan = &installPlan{dir: targetDir}
			byDir[targetDir] = plan
			orderedDirs = append(orderedDirs, targetDir)
		}
		plan.hosts = append(plan.hosts, host)
	}

	plans := make([]installPlan, 0, len(orderedDirs))
	for _, dir := range orderedDirs {
		plan := byDir[dir]
		installSkills, err := checkOverwrite(opts, selectedSkills, plan.dir, canPrompt)
		if err != nil {
			return nil, err
		}
		if len(installSkills) == 0 {
			fmt.Fprintf(opts.IO.ErrOut, "No skills to install in %s for %s.\n", friendlyDir(plan.dir), formatPlanHosts(plan.hosts))
			continue
		}
		plan.skills = installSkills
		plans = append(plans, *plan)
	}

	return plans, nil
}

func checkOverwrite(opts *InstallOptions, skills []discovery.Skill, targetDir string, canPrompt bool) ([]discovery.Skill, error) {
	var existing, fresh []discovery.Skill
	for _, s := range skills {
		dir := filepath.Join(targetDir, s.Name)
		if _, err := os.Stat(dir); err == nil {
			existing = append(existing, s)
		} else {
			fresh = append(fresh, s)
		}
	}

	if len(existing) == 0 {
		return skills, nil
	}

	if opts.Force {
		return skills, nil
	}

	if !canPrompt {
		names := make([]string, len(existing))
		for i, s := range existing {
			names[i] = s.DisplayName()
		}
		return nil, fmt.Errorf("skills already installed: %s (use --force to overwrite)", strings.Join(names, ", "))
	}

	var confirmed []discovery.Skill
	for _, s := range existing {
		prompt := existingSkillPrompt(targetDir, s)
		ok, err := opts.Prompter.Confirm(prompt, false)
		if err != nil {
			return nil, err
		}
		if ok {
			confirmed = append(confirmed, s)
		} else {
			fmt.Fprintf(opts.IO.ErrOut, "Skipping %s\n", s.DisplayName())
		}
	}

	return append(fresh, confirmed...), nil
}

