func selectSkill(opts *PreviewOptions, skills []discovery.Skill) (discovery.Skill, error) {
	if opts.SkillName != "" {
		for _, s := range skills {
			if s.DisplayName() == opts.SkillName || s.Name == opts.SkillName {
				return s, nil
			}
		}

		for _, s := range skills {
			if s.InstallName() == opts.SkillName {
				return s, nil
			}
		}
		return discovery.Skill{}, fmt.Errorf("skill %q not found in %s", opts.SkillName, ghrepo.FullName(opts.repo))
	}

	if !opts.IO.CanPrompt() {
		return discovery.Skill{}, fmt.Errorf("must specify a skill name when not running interactively")
	}

	choices := make([]string, len(skills))
	for i, s := range skills {
		choices[i] = s.DisplayName()
	}

	idx, err := opts.Prompter.Select("Select a skill to preview:", "", choices)
	if err != nil {
		return discovery.Skill{}, err
	}

	return skills[idx], nil
}

func sortTree(node *treeNode) {
	sort.Slice(node.children, func(i, j int) bool {
		if node.children[i].isDir != node.children[j].isDir {
			return node.children[i].isDir
		}
		return node.children[i].name < node.children[j].name
	})
	for _, child := range node.children {
		if child.isDir {
			sortTree(child)
		}
	}
}

// addAgentSkillsTopic adds the "agent-skills" topic to the repo, preserving existing topics.
func addAgentSkillsTopic(client *api.Client, host, owner, repo string) error {
	apiPath, err := safeurl.JoinPath("repos", owner, repo, "topics")
	if err != nil {
		return err
	}

	// Fetch existing topics
	var resp repoTopicsResponse
	if err := client.REST(host, "GET", apiPath.String(), nil, &resp); err != nil {
		return fmt.Errorf("could not fetch existing topics: %w", err)
	}

	if slices.Contains(resp.Names, "agent-skills") {
		return nil
	}

	topics := append(resp.Names, "agent-skills")
	topicsJSON, err := json.Marshal(map[string][]string{"names": topics})
	if err != nil {
		return fmt.Errorf("could not serialize topics: %w", err)
	}
	return client.REST(host, "PUT", apiPath.String(), bytes.NewReader(topicsJSON), nil)
}

