		}

		diagnostics = append(diagnostics, publishDiagnostic{
			severity:	"warning",
			message: fmt.Sprintf(
				"%s/ contains installed skills and should be added to .gitignore to avoid publishing other authors' content",
				relPath),
		})
	}

	return diagnostics
}

