	apiClient := api.NewClientFromHTTP(client)
	u.SetQuery("per_page", "100")
	var pageURL safeurl.SafeURL = u
	for pageURL.String() != "" {
		response := struct {
			Variables []shared.Variable
		}{}
		next, err := apiClient.RESTWithNext(host, "GET", pageURL.String(), nil, &response)
		if err != nil {
			return nil, err
		}
