func (ia *InputAnswer) WriteAnswer(name string, value any) error {
	if s, ok := value.(string); ok {
		ia.providedInputs[name] = s
		return nil
	}

	if rv, ok := value.(reflect.Value); ok {
		ia.providedInputs[name] = rv.String()
