}

// Partition takes a slice of any type T and separates it into two slices
// of the same type based on the provided predicate function. Any item
// that returns true for the predicate will be included in the first slice
// returned, and any item that returns false for the predicate will be
// included in the second slice returned.
func Partition[T any](slice []T, predicate func(T) bool) ([]T, []T) {
	var matching, nonMatching []T
	for _, item := range slice {
		if predicate(item) {
			matching = append(matching, item)
		} else {
			nonMatching = append(nonMatching, item)
		}
	}
	return matching, nonMatching
}

// RangeArgs is cobra.RangeArgs with the usage errors ExactArgs gives: more
// than max arguments is "too many arguments", and fewer than min is msg, so
// the command can say which argument is missing. Both are flag errors, which
// print the usage.
func RangeArgs(min, max int, msg string) cobra.PositionalArgs {
	return func(cmd *cobra.Command, args []string) error {
		if len(args) > max {
			return FlagErrorf("too many arguments")
		}

		if len(args) < min {
			return FlagErrorf("%s", msg)
		}

		return nil
	}
}

func ReadFile(filename string, stdin io.ReadCloser) ([]byte, error) {
	if filename == "-" {
		b, err := io.ReadAll(stdin)
		_ = stdin.Close()
		return b, err
	}

	return os.ReadFile(filename)
}

// ReadMarkdownBodyFile reads Markdown from path and returns its base directory
// for resolving local attachment references. Standard input has no base
// directory.
func ReadMarkdownBodyFile(path string, stdin io.ReadCloser) (content, dir string, err error) {
	b, err := ReadFile(path, stdin)
	if err != nil {
		return "", "", err
	}
	if path != "-" {
		dir = filepath.Dir(path)
	}
	return string(b), dir, nil
}

// RecordTelemetry instruments a command with an invocation-owned telemetry event.
func RecordTelemetry(cmd *cobra.Command, telemetry ghtelemetry.EventRecorder) {
	if isTelemetryDisabled(cmd) {
		return
	}

	if cmd.RunE == nil {
		return
	}

	var event ghtelemetry.PendingEvent
	currentArgs := cmd.Args
	cmd.Args = func(cmd *cobra.Command, args []string) error {
		event = telemetry.Begin(ghtelemetry.Event{
			Type:	"command_invocation",
			Dimensions: ghtelemetry.Dimensions{
				"command":	cmd.CommandPath(),
				"flags":	telemetryFlags(cmd),
			},
		})
		if currentArgs != nil {
			return currentArgs(cmd, args)
		}
		return nil
	}

	currentRunE := cmd.RunE
	cmd.RunE = func(cmd *cobra.Command, args []string) error {
		runErr := currentRunE(cmd, args)

		event.UpsertDimensions(ghtelemetry.Dimensions{"flags": telemetryFlags(cmd)})
		return runErr
	}
}

// RecordTelemetryForSubcommands instruments all descendants of a command.
func RecordTelemetryForSubcommands(cmd *cobra.Command, telemetry ghtelemetry.EventRecorder) {
	for _, c := range cmd.Commands() {
		RecordTelemetry(c, telemetry)
		RecordTelemetryForSubcommands(c, telemetry)
	}
}

// RegisterBranchCompletionFlags suggests and autocompletes known remote git branches for flags passed
func RegisterBranchCompletionFlags(gitc gitClient, cmd *cobra.Command, flags ...string) error {
	for _, flag := range flags {
		err := cmd.RegisterFlagCompletionFunc(flag, func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if repoFlag := cmd.Flag("repo"); repoFlag != nil && repoFlag.Changed {
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
			return gitc.TrackingBranchNames(context.TODO(), toComplete), cobra.ShellCompDirectiveNoFileComp
		})
		if err != nil {
			return err
		}
	}
	return nil
}

